import { createApiRoute as __createApiRoute } from '../../../lib/platform/routeFactory';

/**
 * GET /api/super-admin/savings-report
 *
 * Returns the Redis-ops savings generated by the user-intent driven scheduler.
 *
 * Response:
 *   {
 *     date:               "2026-03-25",
 *     skippedJobsCount:   142,
 *     skippedRedisOpsEst: 2840,
 *     byReason: {
 *       feature_disabled:       80,
 *       no_active_companies:    40,
 *       company_inactive:       12,
 *       frequency_not_elapsed:  10,
 *     },
 *     summary: "Saved ~2.8k Redis ops today by skipping 142 unused job runs",
 *     history: [
 *       { date: "2026-03-19", skippedJobs: 98,  skippedOps: 1960 },
 *       ...
 *     ]
 *   }
 *
 * Auth: requireCapability(SUPER_ADMIN_DASHBOARD_VIEW)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { getSavingsReport } from '../../../backend/services/intentExecutionService';
import { requireCapability } from '../../../backend/security/requireCapability';
import { SUPER_ADMIN_DASHBOARD_VIEW } from '../../../shared/contracts/security';

// 2026-11-11: platform VIEW capability; requireCapability answers 401/403 itself.
// The legacy super-admin cookie arm is gone.
async function requireSuperAdmin(req: NextApiRequest, res: NextApiResponse): Promise<boolean> {
  const guard = await requireCapability(req, res, {
    capability: SUPER_ADMIN_DASHBOARD_VIEW,
    reason: '/api/super-admin/savings-report read',
  });
  return guard.ok === true;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return res.status(405).json({ error: 'Method not allowed' });
  if (!(await requireSuperAdmin(req, res))) return;

  const report = await getSavingsReport();
  return res.status(200).json(report);
}

// W0-1 (Gate A): canonical route pipeline — pass-through observability + request context.
export default __createApiRoute(handler, { route: '/api/super-admin/savings-report' });
